AssistantMessageToolRequest(name='create', tool_call_id='tooluse_EQo5ldNdsXBO1GcmUkj6n6', arguments={'file_text': '/* ─── Reset & tokens ──────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #ffffff;
  --color-surface:     #f8f8f6;
  --color-surface-2:   #f0efea;
  --color-border:      #e2e0d9;
  --color-text:        #1a1a18;
  --color-text-muted:  #6b6860;
  --color-accent:      #1a3c5e;
  --color-accent-light:#e8f0f8;
  --color-deal:        #c0392b;
  --color-deal-bg:     #fdf0ef;
  --color-deal-border: #f5c6c3;
  --color-focus:       #0057b7;

  --radius-sm:   4px;
  --radius-md:   8px;
  --radius-lg:   16px;
  --radius-pill: 999px;

  --shadow-card: 0 1px 4px rgba(0,0,0,.06), 0 4px 16px rgba(0,0,0,.06);
  --shadow-hover: 0 4px 12px rgba(0,0,0,.1), 0 8px 32px rgba(0,0,0,.08);

  --space-xs:  4px;
  --space-sm:  8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 40px;
  --space-2xl:64px;

  --font-sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-serif: Georgia, "Times New Roman", serif;
}

/* ─── Accessibility: skip link ──────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: var(--space-md);
  left: var(--space-md);
  z-index: 9999;
  padding: var(--space-sm) var(--space-md);
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
}
.skip-link:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  width: 1px;
  overflow: hidden;
  white-space: nowrap;
}

/* ─── Focus ring ─────────────────────────────────────────────────────────── */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

/* ─── Base typography ────────────────────────────────────────────────────── */
body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
}
h1, h2, h3, h4 { line-height: 1.25; }
a { color: inherit; }
ul { list-style: none; }
img, svg { display: block; }
button { font-family: inherit; cursor: pointer; }

/* ─── Utility ────────────────────────────────────────────────────────────── */
.sr-only {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.container {
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: var(--space-lg);
}

/* ─── Header ─────────────────────────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  height: 64px;
}

/* Logo */
.site-logo {
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  flex-shrink: 0;
}
.site-logo__mark {
  width: 36px;
  height: 36px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: -.5px;
}
.site-logo__name {
  font-weight: 700;
  font-size: 1.125rem;
  letter-spacing: -.3px;
  color: var(--color-text);
}

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav__list {
  display: flex;
  gap: var(--space-xs);
  align-items: center;
}
.primary-nav__list a {
  display: block;
  padding: var(--space-xs) var(--space-sm);
  text-decoration: none;
  font-size: .9375rem;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  transition: color .15s, background .15s;
}
.primary-nav__list a:hover,
.primary-nav__list a[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface-2);
}
.primary-nav__list a[aria-current="page"] {
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin-left: auto;
}
.icon-btn {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-xs) var(--space-sm);
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-text);
  font-size: .875rem;
  text-decoration: none;
  transition: background .15s, border-color .15s;
}
.icon-btn:hover { background: var(--color-surface-2); border-color: var(--color-border); }
.icon-btn svg { flex-shrink: 0; }

.cart-btn {
  position: relative;
  background: var(--color-accent);
  color: #fff;
  border-color: transparent;
}
.cart-btn:hover { background: #162f4a; border-color: transparent; }
.cart-count {
  position: absolute;
  top: -6px;
  right: -6px;
  min-width: 18px;
  height: 18px;
  padding-inline: 4px;
  background: var(--color-deal);
  color: #fff;
  border-radius: var(--radius-pill);
  font-size: .6875rem;
  font-weight: 700;
  display: grid;
  place-items: center;
  line-height: 1;
  pointer-events: none;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-text);
}
.menu-toggle[aria-expanded="true"] .icon-open  { display: none; }
.menu-toggle[aria-expanded="false"] .icon-close { display: none; }

/* ─── Hero ───────────────────────────────────────────────────────────────── */
.hero {
  background: var(--color-accent);
  color: #fff;
  overflow: hidden;
  position: relative;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: var(--space-2xl);
  min-height: 480px;
  padding-block: var(--space-2xl);
}
.hero__eyebrow {
  display: inline-block;
  font-size: .8125rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  background: rgba(255,255,255,.15);
  padding: var(--space-xs) var(--space-md);
  border-radius: var(--radius-pill);
  margin-bottom: var(--space-md);
}
.hero__title {
  font-size: clamp(2rem, 4vw, 3.25rem);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.1;
  margin-bottom: var(--space-md);
}
.hero__subtitle {
  font-size: 1.125rem;
  color: rgba(255,255,255,.8);
  max-width: 38ch;
  margin-bottom: var(--space-xl);
}
.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: 12px var(--space-lg);
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 600;
  text-decoration: none;
  border: 2px solid transparent;
  transition: background .15s, color .15s, border-color .15s, transform .1s;
  white-space: nowrap;
}
.btn:active { transform: scale(.98); }
.btn--primary { background: #fff; color: var(--color-accent); }
.btn--primary:hover { background: #f0f0f0; }
.btn--ghost { background: transparent; color: #fff; border-color: rgba(255,255,255,.5); }
.btn--ghost:hover { background: rgba(255,255,255,.1); border-color: #fff; }
.btn--accent { background: var(--color-accent); color: #fff; border-color: var(--color-accent); }
.btn--accent:hover { background: #162f4a; }
.btn--outline { background: transparent; color: var(--color-accent); border-color: var(--color-accent); }
.btn--outline:hover { background: var(--color-accent-light); }

.hero__visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-md);
}
.hero-card {
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.18);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}
.hero-card--tall { grid-row: span 2; }
.hero-card__emoji { font-size: 2.5rem; line-height: 1; }
.hero-card__label { font-size: .875rem; opacity: .8; }
.hero-card__value { font-weight: 700; font-size: 1.25rem; }

/* ─── Announcement bar ───────────────────────────────────────────────────── */
.announce-bar {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  text-align: center;
  padding: var(--space-sm) var(--space-md);
  font-size: .875rem;
  color: var(--color-text-muted);
  position: relative;
}
.announce-bar strong { color: var(--color-text); }
.announce-bar__dismiss {
  position: absolute;
  right: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  padding: var(--space-xs);
  border-radius: var(--radius-sm);
  line-height: 1;
  font-size: 1rem;
}
.announce-bar__dismiss:hover { color: var(--color-text); background: var(--color-surface-2); }

/* ─── Section shared ─────────────────────────────────────────────────────── */
.section { padding-block: var(--space-2xl); }
.section--alt { background: var(--color-surface); }
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-md);
  margin-bottom: var(--space-xl);
  flex-wrap: wrap;
}
.section-header h2 {
  font-size: clamp(1.375rem, 2.5vw, 1.875rem);
  font-weight: 800;
  letter-spacing: -.02em;
}
.section-header__eyebrow {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
  display: block;
  margin-bottom: var(--space-xs);
}
.see-all-link {
  font-size: .9375rem;
  font-weight: 600;
  color: var(--color-accent);
  text-decoration: none;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border-radius: var(--radius-sm);
  padding: 2px 4px;
}
.see-all-link:hover { text-decoration: underline; }

/* ─── Product grid ───────────────────────────────────────────────────────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: var(--space-lg);
}
.product-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow .2s, transform .2s;
}
.product-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }

.product-card__image-wrap {
  background: var(--color-surface);
  aspect-ratio: 1;
  overflow: hidden;
  position: relative;
}
.product-card__image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .3s;
}
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover .product-card__image-wrap img { transform: scale(1.05); }
}
.product-card__badge {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  font-size: .6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .05em;
  padding: 2px 8px;
  border-radius: var(--radius-pill);
}
.badge--new     { background: var(--color-accent); color: #fff; }
.badge--sale    { background: var(--color-deal); color: #fff; }
.badge--popular { background: #5a3e8c; color: #fff; }

.product-card__body {
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  flex: 1;
}
.product-card__category {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}
.product-card__name {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.35;
}
.product-card__name a {
  text-decoration: none;
  color: var(--color-text);
}
.product-card__name a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.product-card__image-wrap { position: static; }
.product-card { position: relative; }
.product-card__name a:focus-visible { outline: none; }
.product-card:has(.product-card__name a:focus-visible) {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}
.product-card__rating {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: .8125rem;
  color: var(--color-text-muted);
}
.stars { color: #f59e0b; letter-spacing: -.05em; }
.product-card__price-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
  margin-top: auto;
  padding-top: var(--space-sm);
}
.price {
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--color-text);
}
.price--original {
  font-size: .9375rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
  font-weight: 400;
}
.price--sale { color: var(--color-deal); }
.product-card__footer {
  padding: 0 var(--space-md) var(--space-md);
}
.add-to-cart-btn {
  width: 100%;
  padding: 10px;
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 600;
  transition: background .15s;
  position: relative;
  z-index: 1;
}
.add-to-cart-btn:hover { background: #162f4a; }

/* ─── Deals strip ────────────────────────────────────────────────────────── */
.deals-strip {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}
.deal-card {
  background: var(--color-deal-bg);
  border: 1px solid var(--color-deal-border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  display: flex;
  gap: var(--space-md);
  align-items: center;
  position: relative;
  transition: box-shadow .2s;
}
.deal-card:hover { box-shadow: var(--shadow-hover); }
.deal-card__discount {
  flex-shrink: 0;
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background: var(--color-deal);
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: .625rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .04em;
  line-height: 1.2;
}
.deal-card__discount-pct { font-size: 1.375rem; font-weight: 800; }
.deal-card__content { flex: 1; min-width: 0; }
.deal-card__name {
  font-weight: 700;
  font-size: 1rem;
  margin-bottom: var(--space-xs);
}
.deal-card__name a {
  text-decoration: none;
  color: var(--color-text);
}
.deal-card__name a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.deal-card:has(.deal-card__name a:focus-visible) {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}
.deal-card__name a:focus-visible { outline: none; }
.deal-card__meta { font-size: .875rem; color: var(--color-text-muted); }
.deal-card__timer {
  font-size: .75rem;
  font-weight: 600;
  color: var(--color-deal);
  margin-top: var(--space-xs);
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ─── Category grid ──────────────────────────────────────────────────────── */
.category-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: var(--space-md);
}
.category-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-lg) var(--space-md);
  text-align: center;
  text-decoration: none;
  color: var(--color-text);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-sm);
  transition: background .15s, box-shadow .15s, transform .15s;
  font-weight: 600;
  font-size: .9375rem;
}
.category-card:hover {
  background: var(--color-accent-light);
  border-color: var(--color-accent);
  transform: translateY(-2px);
  box-shadow: var(--shadow-card);
  text-decoration: underline;
}
.category-card__icon {
  font-size: 2rem;
  line-height: 1;
  display: block;
  aria-hidden: true;
}

/* ─── Editorial ──────────────────────────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: var(--space-lg);
}
.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  transition: box-shadow .2s;
}
.editorial-card:hover { box-shadow: var(--shadow-hover); }
.editorial-card--featured {
  grid-row: span 2;
}
.editorial-card__image {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  background: var(--color-surface-2);
}
.editorial-card--featured .editorial-card__image { aspect-ratio: 4/5; flex: 1; }
.editorial-card__body {
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}
.editorial-card__tag {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
}
.editorial-card__title {
  font-size: 1.125rem;
  font-weight: 700;
  line-height: 1.3;
}
.editorial-card--featured .editorial-card__title { font-size: 1.375rem; }
.editorial-card__title a {
  text-decoration: none;
  color: var(--color-text);
}
.editorial-card__title a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.editorial-card:has(.editorial-card__title a:focus-visible) {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}
.editorial-card__title a:focus-visible { outline: none; }
.editorial-card__excerpt {
  font-size: .9375rem;
  color: var(--color-text-muted);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ─── Promo banner ───────────────────────────────────────────────────────── */
.promo-banner {
  background: linear-gradient(135deg, #1a3c5e 0%, #2d6aa0 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: var(--space-xl) var(--space-2xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
  flex-wrap: wrap;
  margin-block: var(--space-2xl);
}
.promo-banner__content { max-width: 50ch; }
.promo-banner__eyebrow {
  font-size: .8125rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  opacity: .75;
  margin-bottom: var(--space-sm);
}
.promo-banner__title {
  font-size: clamp(1.375rem, 2.5vw, 1.875rem);
  font-weight: 800;
  margin-bottom: var(--space-sm);
}
.promo-banner__subtitle { opacity: .85; }
.promo-banner__actions { display: flex; gap: var(--space-sm); flex-wrap: wrap; }

/* ─── Newsletter ─────────────────────────────────────────────────────────── */
.newsletter { text-align: center; }
.newsletter h2 { margin-bottom: var(--space-sm); }
.newsletter__subtitle { color: var(--color-text-muted); margin-bottom: var(--space-xl); }
.newsletter-form {
  display: flex;
  gap: var(--space-sm);
  max-width: 460px;
  margin-inline: auto;
  flex-wrap: wrap;
}
.newsletter-form__input {
  flex: 1;
  min-width: 200px;
  padding: 12px var(--space-md);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-family: inherit;
  background: var(--color-bg);
  color: var(--color-text);
  transition: border-color .15s;
}
.newsletter-form__input:focus { outline: none; border-color: var(--color-focus); box-shadow: 0 0 0 3px rgba(0,87,183,.2); }
.newsletter-form__input::placeholder { color: var(--color-text-muted); }
.newsletter-status {
  margin-top: var(--space-md);
  font-size: .9375rem;
  min-height: 1.5em;
}
.newsletter-status:not(:empty) { color: var(--color-accent); font-weight: 600; }

/* ─── Footer ─────────────────────────────────────────────────────────────── */
.site-footer {
  background: var(--color-text);
  color: rgba(255,255,255,.75);
  padding-block: var(--space-2xl) var(--space-xl);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-xl);
}
.footer-brand {}
.footer-brand .site-logo { margin-bottom: var(--space-md); }
.footer-brand .site-logo__name { color: #fff; }
.footer-brand__desc { font-size: .9375rem; line-height: 1.6; }
.footer-col h3 {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: rgba(255,255,255,.5);
  margin-bottom: var(--space-md);
}
.footer-col ul { display: flex; flex-direction: column; gap: var(--space-sm); }
.footer-col a {
  text-decoration: none;
  font-size: .9375rem;
  color: rgba(255,255,255,.75);
  border-radius: var(--radius-sm);
  transition: color .15s;
}
.footer-col a:hover { color: #fff; text-decoration: underline; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.12);
  padding-top: var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
  flex-wrap: wrap;
  font-size: .875rem;
}
.social-links { display: flex; gap: var(--space-sm); }
.social-link {
  display: flex;
