  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: var(--radius-sm);
  color: rgba(255,255,255,.75);
  text-decoration: none;
  transition: border-color .15s, color .15s, background .15s;
}
.social-link:hover { border-color: #fff; color: #fff; background: rgba(255,255,255,.1); }

/* ─── Live region ────────────────────────────────────────────────────────── */
#cart-status {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ─── Responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .menu-toggle { display: flex; }

  .primary-nav {
    position: absolute;
    top: 64px;
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--space-md) var(--space-lg);
    z-index: 99;
  }
  .primary-nav[hidden] { display: none; }
  .primary-nav__list { flex-direction: column; align-items: stretch; }
  .primary-nav__list a { font-size: 1rem; padding: var(--space-sm) var(--space-md); }

  .hero-inner {
    grid-template-columns: 1fr;
    min-height: auto;
    padding-block: var(--space-xl);
  }
  .hero__visual { display: none; }

  .editorial-grid {
    grid-template-columns: 1fr;
  }
  .editorial-card--featured { grid-row: span 1; }
  .editorial-card--featured .editorial-card__image { aspect-ratio: 16/9; flex: none; }

  .footer-grid { grid-template-columns: 1fr 1fr; gap: var(--space-xl); }
  .footer-brand { grid-column: span 2; }

  .promo-banner { padding: var(--space-xl); text-align: center; justify-content: center; }
  .promo-banner__content { max-width: 100%; }
}

@media (max-width: 480px) {
  .container { padding-inline: var(--space-md); }
  .product-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
  .deals-strip { grid-template-columns: 1fr; }
  .category-grid { grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: span 1; }
  .hero__title { font-size: 1.875rem; }
}

/* ─── Forced colors / high-contrast ─────────────────────────────────────── */
@media (forced-colors: active) {
  .product-card,
  .deal-card,
  .editorial-card,
  .category-card {
    border: 2px solid ButtonText;
  }
  .add-to-cart-btn,
  .btn--primary,
  .btn--accent {
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }
  .cart-btn { forced-color-adjust: none; background: Highlight; color: HighlightText; }
  .hero { forced-color-adjust: none; background: Canvas; color: CanvasText; border-bottom: 2px solid ButtonText; }
  .promo-banner { forced-color-adjust: none; background: Canvas; color: CanvasText; border: 2px solid ButtonText; }
}

/* ─── Reduced motion ─────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
}

/* ─── Dark mode (respects OS) ───────────────────────────────────────────── */
@media (prefers-color-scheme: dark) {
  :root {
    --color-bg:          #111110;
    --color-surface:     #1c1c1a;
    --color-surface-2:   #262622;
    --color-border:      #323230;
    --color-text:        #f0efea;
    --color-text-muted:  #9e9c94;
    --color-accent-light:#0f1f30;
    --color-deal-bg:     #1f0f0e;
    --color-deal-border: #4a1f1c;
  }
  .site-header { background: var(--color-bg); }
  .product-card { background: var(--color-surface); }
  .hero-card { background: rgba(255,255,255,.08); }
  .newsletter-form__input { background: var(--color-surface); }
}
