@@ -1,0 +1,910 @@
+/* ─── Reset & tokens ──────────────────────────────────────────────────── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --color-bg:          #ffffff;
+  --color-surface:     #f8f8f6;
+  --color-surface-2:   #f0efea;
+  --color-border:      #e2e0d9;
+  --color-text:        #1a1a18;
+  --color-text-muted:  #6b6860;
+  --color-accent:      #1a3c5e;
+  --color-accent-light:#e8f0f8;
+  --color-deal:        #c0392b;
+  --color-deal-bg:     #fdf0ef;
+  --color-deal-border: #f5c6c3;
+  --color-focus:       #0057b7;
+
+  --radius-sm:   4px;
+  --radius-md:   8px;
+  --radius-lg:   16px;
+  --radius-pill: 999px;
+
+  --shadow-card: 0 1px 4px rgba(0,0,0,.06), 0 4px 16px rgba(0,0,0,.06);
+  --shadow-hover: 0 4px 12px rgba(0,0,0,.1), 0 8px 32px rgba(0,0,0,.08);
+
+  --space-xs:  4px;
+  --space-sm:  8px;
+  --space-md: 16px;
+  --space-lg: 24px;
+  --space-xl: 40px;
+  --space-2xl:64px;
+
+  --font-sans: system-ui, -apple-system, "Segoe UI", sans-serif;
+  --font-serif: Georgia, "Times New Roman", serif;
+}
+
+/* ─── Accessibility: skip link ──────────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: var(--space-md);
+  left: var(--space-md);
+  z-index: 9999;
+  padding: var(--space-sm) var(--space-md);
+  background: var(--color-accent);
+  color: #fff;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  text-decoration: none;
+  white-space: nowrap;
+}
+.skip-link:not(:focus):not(:active) {
+  clip: rect(0 0 0 0);
+  clip-path: inset(50%);
+  height: 1px;
+  width: 1px;
+  overflow: hidden;
+  white-space: nowrap;
+}
+
+/* ─── Focus ring ─────────────────────────────────────────────────────────── */
+:focus-visible {
+  outline: 3px solid var(--color-focus);
+  outline-offset: 2px;
+}
+
+/* ─── Base typography ────────────────────────────────────────────────────── */
+body {
+  font-family: var(--font-sans);
+  font-size: 1rem;
+  line-height: 1.6;
+  color: var(--color-text);
+  background: var(--color-bg);
+}
+h1, h2, h3, h4 { line-height: 1.25; }
+a { color: inherit; }
+ul { list-style: none; }
+img, svg { display: block; }
+button { font-family: inherit; cursor: pointer; }
+
+/* ─── Utility ────────────────────────────────────────────────────────────── */
+.sr-only {
+  clip: rect(0 0 0 0);
+  clip-path: inset(50%);
+  height: 1px;
+  overflow: hidden;
+  position: absolute;
+  white-space: nowrap;
+  width: 1px;
+}
+
+.container {
+  max-width: 1280px;
+  margin-inline: auto;
+  padding-inline: var(--space-lg);
+}
+
+/* ─── Header ─────────────────────────────────────────────────────────────── */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 100;
+  background: var(--color-bg);
+  border-bottom: 1px solid var(--color-border);
+}
+.header-inner {
+  display: flex;
+  align-items: center;
+  gap: var(--space-lg);
+  height: 64px;
+}
+
+/* Logo */
+.site-logo {
+  text-decoration: none;
+  display: flex;
+  align-items: center;
+  gap: var(--space-sm);
+  flex-shrink: 0;
+}
+.site-logo__mark {
+  width: 36px;
+  height: 36px;
+  background: var(--color-accent);
+  border-radius: var(--radius-sm);
+  display: grid;
+  place-items: center;
+  color: #fff;
+  font-weight: 800;
+  font-size: 1.1rem;
+  letter-spacing: -.5px;
+}
+.site-logo__name {
+  font-weight: 700;
+  font-size: 1.125rem;
+  letter-spacing: -.3px;
+  color: var(--color-text);
+}
+
+/* Primary nav */
+.primary-nav { flex: 1; }
+.primary-nav__list {
+  display: flex;
+  gap: var(--space-xs);
+  align-items: center;
+}
+.primary-nav__list a {
+  display: block;
+  padding: var(--space-xs) var(--space-sm);
+  text-decoration: none;
+  font-size: .9375rem;
+  border-radius: var(--radius-sm);
+  color: var(--color-text-muted);
+  transition: color .15s, background .15s;
+}
+.primary-nav__list a:hover,
+.primary-nav__list a[aria-current="page"] {
+  color: var(--color-text);
+  background: var(--color-surface-2);
+}
+.primary-nav__list a[aria-current="page"] {
+  font-weight: 600;
+  text-decoration: underline;
+  text-underline-offset: 3px;
+}
+
+/* Header actions */
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: var(--space-sm);
+  margin-left: auto;
+}
+.icon-btn {
+  display: flex;
+  align-items: center;
+  gap: var(--space-xs);
+  padding: var(--space-xs) var(--space-sm);
+  border: 1px solid transparent;
+  border-radius: var(--radius-sm);
+  background: transparent;
+  color: var(--color-text);
+  font-size: .875rem;
+  text-decoration: none;
+  transition: background .15s, border-color .15s;
+}
+.icon-btn:hover { background: var(--color-surface-2); border-color: var(--color-border); }
+.icon-btn svg { flex-shrink: 0; }
+
+.cart-btn {
+  position: relative;
+  background: var(--color-accent);
+  color: #fff;
+  border-color: transparent;
+}
+.cart-btn:hover { background: #162f4a; border-color: transparent; }
+.cart-count {
+  position: absolute;
+  top: -6px;
+  right: -6px;
+  min-width: 18px;
+  height: 18px;
+  padding-inline: 4px;
+  background: var(--color-deal);
+  color: #fff;
+  border-radius: var(--radius-pill);
+  font-size: .6875rem;
+  font-weight: 700;
+  display: grid;
+  place-items: center;
+  line-height: 1;
+  pointer-events: none;
+}
+
+/* Mobile menu toggle */
+.menu-toggle {
+  display: none;
+  align-items: center;
+  justify-content: center;
+  width: 40px;
+  height: 40px;
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-sm);
+  background: transparent;
+  color: var(--color-text);
+}
+.menu-toggle[aria-expanded="true"] .icon-open  { display: none; }
+.menu-toggle[aria-expanded="false"] .icon-close { display: none; }
+
+/* ─── Hero ───────────────────────────────────────────────────────────────── */
+.hero {
+  background: var(--color-accent);
+  color: #fff;
+  overflow: hidden;
+  position: relative;
+}
+.hero-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  align-items: center;
+  gap: var(--space-2xl);
+  min-height: 480px;
+  padding-block: var(--space-2xl);
+}
+.hero__eyebrow {
+  display: inline-block;
+  font-size: .8125rem;
+  font-weight: 600;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  background: rgba(255,255,255,.15);
+  padding: var(--space-xs) var(--space-md);
+  border-radius: var(--radius-pill);
+  margin-bottom: var(--space-md);
+}
+.hero__title {
+  font-size: clamp(2rem, 4vw, 3.25rem);
+  font-weight: 800;
+  letter-spacing: -.02em;
+  line-height: 1.1;
+  margin-bottom: var(--space-md);
+}
+.hero__subtitle {
+  font-size: 1.125rem;
+  color: rgba(255,255,255,.8);
+  max-width: 38ch;
+  margin-bottom: var(--space-xl);
+}
+.hero__actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: var(--space-sm);
+}
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: var(--space-xs);
+  padding: 12px var(--space-lg);
+  border-radius: var(--radius-md);
+  font-size: .9375rem;
+  font-weight: 600;
+  text-decoration: none;
+  border: 2px solid transparent;
+  transition: background .15s, color .15s, border-color .15s, transform .1s;
+  white-space: nowrap;
+}
+.btn:active { transform: scale(.98); }
+.btn--primary { background: #fff; color: var(--color-accent); }
+.btn--primary:hover { background: #f0f0f0; }
+.btn--ghost { background: transparent; color: #fff; border-color: rgba(255,255,255,.5); }
+.btn--ghost:hover { background: rgba(255,255,255,.1); border-color: #fff; }
+.btn--accent { background: var(--color-accent); color: #fff; border-color: var(--color-accent); }
+.btn--accent:hover { background: #162f4a; }
+.btn--outline { background: transparent; color: var(--color-accent); border-color: var(--color-accent); }
+.btn--outline:hover { background: var(--color-accent-light); }
+
+.hero__visual {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: var(--space-md);
+}
+.hero-card {
+  background: rgba(255,255,255,.12);
+  border: 1px solid rgba(255,255,255,.18);
+  border-radius: var(--radius-lg);
+  padding: var(--space-lg);
+  display: flex;
+  flex-direction: column;
+  gap: var(--space-sm);
+}
+.hero-card--tall { grid-row: span 2; }
+.hero-card__emoji { font-size: 2.5rem; line-height: 1; }
+.hero-card__label { font-size: .875rem; opacity: .8; }
+.hero-card__value { font-weight: 700; font-size: 1.25rem; }
+
+/* ─── Announcement bar ───────────────────────────────────────────────────── */
+.announce-bar {
+  background: var(--color-surface);
+  border-bottom: 1px solid var(--color-border);
+  text-align: center;
+  padding: var(--space-sm) var(--space-md);
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  position: relative;
+}
+.announce-bar strong { color: var(--color-text); }
+.announce-bar__dismiss {
+  position: absolute;
+  right: var(--space-md);
+  top: 50%;
+  transform: translateY(-50%);
+  background: transparent;
+  border: none;
+  color: var(--color-text-muted);
+  padding: var(--space-xs);
+  border-radius: var(--radius-sm);
+  line-height: 1;
