*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #ffffff;
  --color-surface:     #f8f8f6;
  --color-surface-2:   #f0efea;
  --color-border:      #e2e0d9;
  --color-text:        #1a1a18;
  --color-text-muted:  #6b6860;
  --color-accent:      #1a3c5e;
  --color-accent-light:#e8f0f8;
  --color-deal:        #c0392b;
  --color-deal-bg:     #fdf0ef;
  --color-deal-border: #f5c6c3;
  --color-focus:       #0057b7;

  --radius-sm:   4px;
  --radius-md:   8px;
  --radius-lg:   16px;
  --radius-pill: 999px;

  --shadow-card: 0 1px 4px rgba(0,0,0,.06), 0 4px 16px rgba(0,0,0,.06);
  --shadow-hover: 0 4px 12px rgba(0,0,0,.1), 0 8px 32px rgba(0,0,0,.08);

  --space-xs:  4px;
  --space-sm:  8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 40px;
  --space-2xl:64px;

  --font-sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-serif: Georgia, "Times New Roman", serif;
}

/* ─── Accessibility: skip link ──────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: var(--space-md);
  left: var(--space-md);
  z-index: 9999;
  padding: var(--space-sm) var(--space-md);
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
}
.skip-link:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  width: 1px;
  overflow: hidden;
  white-space: nowrap;
}

/* ─── Focus ring ─────────────────────────────────────────────────────────── */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

/* ─── Base typography ────────────────────────────────────────────────────── */
body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
}
h1, h2, h3, h4 { line-height: 1.25; }
a { color: inherit; }
ul { list-style: none; }
img, svg { display: block; }
button { font-family: inherit; cursor: pointer; }

/* ─── Utility ────────────────────────────────────────────────────────────── */
.sr-only {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.container {
