ul { list-style: none; }
img, svg { display: block; }
button { font-family: inherit; cursor: pointer; }

/* ─── Utility ────────────────────────────────────────────────────────────── */
.sr-only {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.container {
  max-width: 1280px;
