+}
+.announce-bar strong { color: var(--color-text); }
+.announce-bar__dismiss {
+  position: absolute;
+  right: var(--space-md);
+  top: 50%;
+  transform: translateY(-50%);
+  background: transparent;
+  border: none;
+  color: var(--color-text-muted);
+  padding: var(--space-xs);
+  border-radius: var(--radius-sm);
+  line-height: 1;
+  font-size: 1rem;
+}
+.announce-bar__dismiss:hover { color: var(--color-text); background: var(--color-surface-2); }
+
+/* ─── Section shared ─────────────────────────────────────────────────────── */
+.section { padding-block: var(--space-2xl); }
+.section--alt { background: var(--color-surface); }
+.section-header {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: var(--space-md);
+  margin-bottom: var(--space-xl);
+  flex-wrap: wrap;
+}
+.section-header h2 {
+  font-size: clamp(1.375rem, 2.5vw, 1.875rem);
+  font-weight: 800;
+  letter-spacing: -.02em;
+}
+.section-header__eyebrow {
+  font-size: .75rem;
+  font-weight: 600;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  display: block;
+  margin-bottom: var(--space-xs);
+}
+.see-all-link {
+  font-size: .9375rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  text-decoration: none;
+  white-space: nowrap;
+  display: inline-flex;
