+  padding: 2px 8px;
+  border-radius: var(--radius-pill);
+}
+.badge--new     { background: var(--color-accent); color: #fff; }
+.badge--sale    { background: var(--color-deal); color: #fff; }
+.badge--popular { background: #5a3e8c; color: #fff; }
+
+.product-card__body {
+  padding: var(--space-md);
+  display: flex;
+  flex-direction: column;
+  gap: var(--space-xs);
+  flex: 1;
+}
+.product-card__category {
+  font-size: .75rem;
+  font-weight: 600;
+  letter-spacing: .05em;
+  text-transform: uppercase;
+  color: var(--color-text-muted);
+}
+.product-card__name {
+  font-size: 1rem;
+  font-weight: 600;
+  line-height: 1.35;
+}
+.product-card__name a {
+  text-decoration: none;
+  color: var(--color-text);
+}
+.product-card__name a::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+}
+.product-card__image-wrap { position: static; }
+.product-card { position: relative; }
+.product-card__name a:focus-visible { outline: none; }
+.product-card:has(.product-card__name a:focus-visible) {
