+  color: var(--color-text-muted);
+}
+.stars { color: #f59e0b; letter-spacing: -.05em; }
+.product-card__price-row {
+  display: flex;
+  align-items: baseline;
+  gap: var(--space-sm);
+  margin-top: auto;
+  padding-top: var(--space-sm);
+}
+.price {
+  font-weight: 700;
+  font-size: 1.125rem;
+  color: var(--color-text);
+}
+.price--original {
+  font-size: .9375rem;
+  color: var(--color-text-muted);
