+  font-weight: 600;
+  transition: background .15s;
+  position: relative;
+  z-index: 1;
+}
+.add-to-cart-btn:hover { background: #162f4a; }
+
+/* ─── Deals strip ────────────────────────────────────────────────────────── */
+.deals-strip {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
+  gap: var(--space-md);
