+  gap: var(--space-md);
+  align-items: center;
+  position: relative;
+  transition: box-shadow .2s;
+}
+.deal-card:hover { box-shadow: var(--shadow-hover); }
+.deal-card__discount {
+  flex-shrink: 0;
+  width: 68px;
+  height: 68px;
+  border-radius: 50%;
+  background: var(--color-deal);
+  color: #fff;
