+.deal-card__discount-pct { font-size: 1.375rem; font-weight: 800; }
+.deal-card__content { flex: 1; min-width: 0; }
+.deal-card__name {
+  font-weight: 700;
+  font-size: 1rem;
+  margin-bottom: var(--space-xs);
+}
+.deal-card__name a {
+  text-decoration: none;
+  color: var(--color-text);
+}
+.deal-card__name a::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+}
+.deal-card:has(.deal-card__name a:focus-visible) {
+  outline: 3px solid var(--color-focus);
+  outline-offset: 2px;
+}
+.deal-card__name a:focus-visible { outline: none; }
+.deal-card__meta { font-size: .875rem; color: var(--color-text-muted); }
+.deal-card__timer {
+  font-size: .75rem;
+  font-weight: 600;
+  color: var(--color-deal);
+  margin-top: var(--space-xs);
+  display: flex;
+  align-items: center;
+  gap: 4px;
+}
+
+/* ─── Category grid ──────────────────────────────────────────────────────── */
+.category-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
+  gap: var(--space-md);
+}
+.category-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  padding: var(--space-lg) var(--space-md);
+  text-align: center;
+  text-decoration: none;
+  color: var(--color-text);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: var(--space-sm);
+  transition: background .15s, box-shadow .15s, transform .15s;
+  font-weight: 600;
+  font-size: .9375rem;
+}
+.category-card:hover {
+  background: var(--color-accent-light);
+  border-color: var(--color-accent);
+  transform: translateY(-2px);
+  box-shadow: var(--shadow-card);
+  text-decoration: underline;
+}
+.category-card__icon {
+  font-size: 2rem;
+  line-height: 1;
+  display: block;
+  aria-hidden: true;
+}
+
+/* ─── Editorial ──────────────────────────────────────────────────────────── */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  grid-template-rows: auto auto;
+  gap: var(--space-lg);
+}
+.editorial-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  position: relative;
+  transition: box-shadow .2s;
+}
+.editorial-card:hover { box-shadow: var(--shadow-hover); }
+.editorial-card--featured {
+  grid-row: span 2;
+}
+.editorial-card__image {
+  width: 100%;
+  aspect-ratio: 16/9;
+  object-fit: cover;
+  background: var(--color-surface-2);
+}
+.editorial-card--featured .editorial-card__image { aspect-ratio: 4/5; flex: 1; }
+.editorial-card__body {
+  padding: var(--space-lg);
+  display: flex;
+  flex-direction: column;
+  gap: var(--space-xs);
+}
+.editorial-card__tag {
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+}
+.editorial-card__title {
+  font-size: 1.125rem;
+  font-weight: 700;
+  line-height: 1.3;
+}
+.editorial-card--featured .editorial-card__title { font-size: 1.375rem; }
+.editorial-card__title a {
+  text-decoration: none;
+  color: var(--color-text);
+}
+.editorial-card__title a::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+}
+.editorial-card:has(.editorial-card__title a:focus-visible) {
+  outline: 3px solid var(--color-focus);
+  outline-offset: 2px;
+}
+.editorial-card__title a:focus-visible { outline: none; }
+.editorial-card__excerpt {
+  font-size: .9375rem;
+  color: var(--color-text-muted);
+  display: -webkit-box;
+  -webkit-line-clamp: 3;
+  -webkit-box-orient: vertical;
+  overflow: hidden;
+}
+
+/* ─── Promo banner ───────────────────────────────────────────────────────── */
+.promo-banner {
+  background: linear-gradient(135deg, #1a3c5e 0%, #2d6aa0 100%);
+  color: #fff;
+  border-radius: var(--radius-lg);
+  padding: var(--space-xl) var(--space-2xl);
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: var(--space-xl);
+  flex-wrap: wrap;
+  margin-block: var(--space-2xl);
+}
+.promo-banner__content { max-width: 50ch; }
+.promo-banner__eyebrow {
+  font-size: .8125rem;
+  font-weight: 600;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  opacity: .75;
+  margin-bottom: var(--space-sm);
+}
+.promo-banner__title {
+  font-size: clamp(1.375rem, 2.5vw, 1.875rem);
