+.promo-banner__actions { display: flex; gap: var(--space-sm); flex-wrap: wrap; }
+
+/* ─── Newsletter ─────────────────────────────────────────────────────────── */
+.newsletter { text-align: center; }
+.newsletter h2 { margin-bottom: var(--space-sm); }
+.newsletter__subtitle { color: var(--color-text-muted); margin-bottom: var(--space-xl); }
+.newsletter-form {
+  display: flex;
+  gap: var(--space-sm);
+  max-width: 460px;
+  margin-inline: auto;
+  flex-wrap: wrap;
+}
+.newsletter-form__input {
+  flex: 1;
+  min-width: 200px;
+  padding: 12px var(--space-md);
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-md);
