  'use strict';

  /* ── Mobile nav toggle ─────────────────────────────────────────────────── */
  const menuToggle = document.getElementById('menu-toggle');
  const primaryNav = document.getElementById('primary-nav');

  if (menuToggle && primaryNav) {
    menuToggle.addEventListener('click', () => {
      const expanded = menuToggle.getAttribute('aria-expanded') === 'true';
      menuToggle.setAttribute('aria-expanded', String(!expanded));
      primaryNav.hidden = expanded;
    });

    // Close nav on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && menuToggle.getAttribute('aria-expanded') === 'true') {
        menuToggle.setAttribute('aria-expanded', 'false');
        primaryNav.hidden = true;
        menuToggle.focus();
      }
    });

    // Close nav on outside click
    document.addEventListener('click', (e) => {
      if (!primaryNav.hidden && !primaryNav.contains(e.target) && e.target !== menuToggle) {
        menuToggle.setAttribute('aria-expanded', 'false');
        primaryNav.hidden = true;
      }
    });
  }

  /* ── Announcement bar dismiss ──────────────────────────────────────────── */
  const announceBar = document.getElementById('announce-bar');
  const dismissBtn = document.getElementById('dismiss-announce');
  if (dismissBtn && announceBar) {
    dismissBtn.addEventListener('click', () => {
      announceBar.hidden = true;
    });
  }

  /* ── Cart state ────────────────────────────────────────────────────────── */
  let cartCount = 0;
  const cartCountEl = document.getElementById('cart-count');
  const cartStatus = document.getElementById('cart-status');

  function updateCart(productName) {
    cartCount += 1;
    if (cartCountEl) {
      cartCountEl.textContent = cartCount;
      cartCountEl.hidden = cartCount === 0;
    }
    if (cartStatus) {
      cartStatus.textContent = `${productName} added to cart. Cart has ${cartCount} item${cartCount !== 1 ? 's' : ''}.`;
    }
    // Briefly announce then clear to allow repeat announcements
    setTimeout(() => {
      if (cartStatus) cartStatus.textContent = '';
    }, 4000);
  }

  document.querySelectorAll('[data-add-to-cart]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const name = btn.dataset.addToCart;
      updateCart(name);

      // Visual feedback
      const originalText = btn.textContent;
      btn.textContent = '✓ Added';
      btn.disabled = true;
      setTimeout(() => {
        btn.textContent = originalText;
        btn.disabled = false;
      }, 1500);
    });
  });

  /* ── Deal countdown timers ─────────────────────────────────────────────── */
  document.querySelectorAll('[data-ends-in]').forEach((el) => {
    let seconds = parseInt(el.dataset.endsIn, 10);
    const timerEl = el.querySelector('[data-timer]');
    if (!timerEl) return;

    function formatTime(s) {
      const h = Math.floor(s / 3600);
      const m = Math.floor((s % 3600) / 60);
      const sec = s % 60;
      return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
    }

    timerEl.textContent = formatTime(seconds);
    const interval = setInterval(() => {
      seconds -= 1;
      if (seconds <= 0) {
        clearInterval(interval);
        timerEl.textContent = 'Expired';
        return;
      }
      timerEl.textContent = formatTime(seconds);
    }, 1000);
  });

  /* ── Newsletter form ───────────────────────────────────────────────────── */
  const newsletterForm = document.getElementById('newsletter-form');
  const newsletterStatus = document.getElementById('newsletter-status');

  if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const emailInput = newsletterForm.querySelector('input[type="email"]');
      if (!emailInput || !emailInput.value.trim()) return;

      if (newsletterStatus) {
        newsletterStatus.textContent = 'You\'re subscribed! Check your inbox for a welcome offer.';
      }
      emailInput.value = '';
      emailInput.focus();
    });
  }
})();
